import { z } from 'zod';

export const taskListKind = 'fictional.task-list';
export const taskListVersion = 1;
export const taskListMediaType = 'application/vnd.fictional.task-list+json';
const encoder = new TextEncoder();
const text = (maximum: number) => z.string().min(1).refine(value => encoder.encode(value).length <= maximum
  && !/[\uD800-\uDFFF]/u.test(value) && value.trim().length > 0);
const id = text(128), title = text(2048);
const item = z.object({ id, title, completed: z.boolean() }).strict();
const documentSchema = z.object({ kind: z.literal(taskListKind), version: z.literal(taskListVersion), items: z.array(item).max(100) }).strict()
  .refine(value => new Set(value.items.map(entry => entry.id)).size === value.items.length, 'Duplicate task ID');
const operationsSchema = z.array(z.discriminatedUnion('kind', [
  z.object({ kind: z.literal('add'), id, title }).strict(),
  z.object({ kind: z.literal('rename'), id, title }).strict(),
  z.object({ kind: z.literal('set-completed'), id, completed: z.boolean() }).strict(),
  z.object({ kind: z.literal('remove'), id }).strict(),
])).min(1).max(100);
export interface TaskListDocument {
  readonly kind: typeof taskListKind;
  readonly version: typeof taskListVersion;
  readonly items: readonly Readonly<z.infer<typeof item>>[];
}
export type TaskListOperation = Readonly<z.infer<typeof operationsSchema>[number]>;
function bounded(text: string): string {
  if (encoder.encode(text).length > 65_536) throw new TypeError('Task list exceeds 65536 bytes');
  return text;
}
export function parseTaskList(value: unknown): TaskListDocument {
  const parsed = documentSchema.parse(value);
  bounded(JSON.stringify(parsed));
  return Object.freeze({ ...parsed, items: Object.freeze(parsed.items.map(entry => Object.freeze(entry))) });
}
export function parseTaskListOperations(value: unknown): readonly TaskListOperation[] {
  const parsed = operationsSchema.parse(value);
  bounded(JSON.stringify(parsed));
  return Object.freeze(parsed.map(operation => Object.freeze(operation)));
}
export function readTaskList(text: string): TaskListDocument { return parseTaskList(JSON.parse(bounded(text))); }
export function serializeTaskList(document: TaskListDocument): string { return bounded(JSON.stringify(parseTaskList(document))); }
export function emptyTaskList(): TaskListDocument { return parseTaskList({ kind: taskListKind, version: taskListVersion, items: [] }); }
export function applyTaskListOperations(document: TaskListDocument, operations: readonly TaskListOperation[]): TaskListDocument {
  const items = parseTaskList(document).items.map(entry => ({ ...entry }));
  for (const operation of parseTaskListOperations(operations)) {
    const position = items.findIndex(entry => entry.id === operation.id);
    if (operation.kind === 'add') {
      if (position !== -1) throw new TypeError('Task ID already exists');
      items.push({ id: operation.id, title: operation.title, completed: false });
    } else {
      const current = items[position];
      if (!current) throw new TypeError('Task ID does not exist');
      switch (operation.kind) {
        case 'rename': items[position] = { ...current, title: operation.title }; break;
        case 'set-completed': items[position] = { ...current, completed: operation.completed }; break;
        case 'remove': items.splice(position, 1); break;
      }
    }
  }
  return parseTaskList({ kind: taskListKind, version: taskListVersion, items });
}

import { z } from 'zod';
import { createTextBuffer } from '@hachej/boring-ui-kit/text-buffer';
import type { TextBufferOptions, TextBufferState } from '@hachej/boring-ui-kit/text-buffer';
import type { EditableViewerController, SaveSelection, SaveResult } from '@hachej/boring-ui-kit/resources';
import type { PresentationCommand, ViewerFeature } from '@hachej/boring-ui-kit/contracts';
import type { ReadResult, ResourceExpectation, ResourceLocator } from '@hachej/boring-files';
import { applyTaskListOperations, emptyTaskList, readTaskList, serializeTaskList, taskListKind, taskListMediaType, taskListVersion } from './task-list-document';
import type { TaskListDocument, TaskListOperation } from './task-list-document';

export interface TaskListState extends TextBufferState { readonly document: TaskListDocument }
export type TaskListOptions = Pick<TextBufferOptions, 'identity' | 'instanceId' | 'epoch' | 'source' | 'client' | 'readOnly' | 'onListenerError'>;
type EditResult = { readonly kind: 'applied' } | { readonly kind: 'stale' | 'conflict' | 'denied' | 'unavailable'; readonly reason: string };
export interface TaskListActions {
  readonly selection: () => SaveSelection;
  readonly edit: (selection: SaveSelection, operations: readonly TaskListOperation[]) => EditResult;
  readonly refresh: () => Promise<ReadResult>;
  readonly discardToRemote: () => Promise<ReadResult>;
  readonly reconcile: () => Promise<SaveResult>;
  readonly abandon: () => Promise<ReadResult>;
}
export interface TaskListTools {
  readonly inspect: PresentationCommand<{ readonly expiresAt: number }, {
    readonly document: TaskListDocument; readonly dirty: boolean; readonly bufferVersion: number; readonly base: ResourceExpectation;
  }, SaveSelection['target']['subject']>;
}
export type TaskListController = EditableViewerController<TaskListState, TaskListActions, TaskListTools>;
const expiry = z.object({ expiresAt: z.number().int().min(Number.MIN_SAFE_INTEGER).max(Number.MAX_SAFE_INTEGER) }).strict();
const locator = z.object({ resource: z.object({ providerId: z.string().min(1).max(256), path: z.string().min(1).max(2048) }).strict(), view: z.object({ kind: z.literal('published') }).strict() }).strict();
const descriptorSchema = z.object({ kind: z.literal(taskListKind), version: z.literal(taskListVersion), title: z.string().max(2048).optional(), source: locator }).strict();
export interface TaskListDescriptor { readonly kind: typeof taskListKind; readonly version: typeof taskListVersion; readonly title?: string; readonly source: ResourceLocator }

function sameBase(left: ResourceExpectation, right: ResourceExpectation): boolean {
  return left.kind === right.kind && left.target.resource.providerId === right.target.resource.providerId && left.target.resource.path === right.target.resource.path
    && left.target.view.kind === right.target.view.kind && (left.target.view.kind === 'published' || right.target.view.kind === 'working' && left.target.view.viewId === right.target.view.viewId)
    && (left.kind === 'absent' || right.kind === 'revision' && left.target.revision === right.target.revision);
}

export function createTaskListController(options: TaskListOptions): TaskListController {
  locator.parse(options.source.kind === 'saved'
    ? { resource: options.source.snapshot.ref.resource, view: options.source.snapshot.ref.view } : options.source.target);
  const source = options.source.kind === 'saved' ? options.source : { ...options.source, text: options.source.text ?? serializeTaskList(emptyTaskList()) };
  if (source.kind === 'new') readTaskList(source.text);
  const buffer = createTextBuffer({ ...options, source, emptyText: serializeTaskList(emptyTaskList()), mediaType: taskListMediaType, readText: snapshot => {
    if (snapshot.mediaType !== taskListMediaType) throw new TypeError('Expected a task-list document');
    const text = new TextDecoder('utf-8', { fatal: true, ignoreBOM: true }).decode(snapshot.bytes);
    readTaskList(text); return text;
  } });
  let state: TaskListState = Object.freeze({ ...buffer.getSnapshot(), document: readTaskList(buffer.getSnapshot().text) });
  const unsubscribe = buffer.subscribe(() => {
    const next = buffer.getSnapshot();
    state = Object.freeze({ ...next, document: next.text === state.text ? state.document : readTaskList(next.text) });
  });
  const selected = (selection: SaveSelection) => {
    const current = buffer.selection().target, proposed = selection.target;
    return proposed.instanceId === current.instanceId && proposed.epoch === current.epoch && proposed.subject.scopeId === current.subject.scopeId
      && proposed.subject.bufferVersion === current.subject.bufferVersion && sameBase(proposed.subject.base, current.subject.base);
  };
  return {
    getSnapshot: () => state, subscribe: buffer.subscribe, flush: buffer.flush,
    dispose: () => { buffer.dispose(); unsubscribe(); },
    actions: {
      selection: buffer.selection,
      edit: (selection, operations) => {
        if (state.lifecycle === 'disposed') return { kind: 'unavailable', reason: 'Viewer is disposed' };
        if (state.readOnly) return { kind: 'denied', reason: 'Viewer is read-only' };
        if (!selected(selection)) return { kind: 'stale', reason: 'Task-list target has changed' };
        let document;
        try { document = applyTaskListOperations(state.document, operations); }
        catch { return { kind: 'conflict', reason: 'Task-list operations are invalid or conflict with the current list' }; }
        buffer.edit(serializeTaskList(document));
        return { kind: 'applied' };
      },
      refresh: () => buffer.refresh(false), discardToRemote: () => buffer.refresh(true), reconcile: buffer.reconcile, abandon: buffer.abandon,
    },
    tools: { inspect: { name: 'inspect_task_list_buffer', input: { jsonSchema: z.toJSONSchema(expiry), parse: value => expiry.parse(value) }, invoke: async (target, input, signal) => {
      if (state.lifecycle === 'disposed') return { kind: 'unavailable', reason: 'Viewer is disposed' };
      if (signal?.aborted) return { kind: 'denied', reason: 'Inspection cancelled' };
      if (expiry.parse(input).expiresAt <= Date.now() || !selected({ target })) return { kind: 'stale', reason: 'Inspection target changed or expired' };
      return { kind: 'applied', value: { document: state.document, dirty: state.dirty, bufferVersion: state.bufferVersion, base: state.base } };
    } } },
  };
}

export function createTaskListFeature(options: TaskListOptions): ViewerFeature<TaskListDescriptor, TaskListController> {
  const captured = { ...options, identity: structuredClone(options.identity), source: structuredClone(options.source) };
  const configured = locator.parse(captured.source.kind === 'saved'
    ? { resource: captured.source.snapshot.ref.resource, view: captured.source.snapshot.ref.view } : captured.source.target);
  return { kind: taskListKind, version: taskListVersion,
    descriptor: { jsonSchema: z.toJSONSchema(descriptorSchema), parse: value => {
      const parsed = descriptorSchema.parse(value);
      return { kind: parsed.kind, version: parsed.version, source: parsed.source, ...(parsed.title === undefined ? {} : { title: parsed.title }) };
    } },
    createController: descriptor => {
      const parsed = descriptorSchema.parse(descriptor);
      if (JSON.stringify(parsed.source) !== JSON.stringify(configured)) throw new TypeError('Descriptor names another task-list source');
      return createTaskListController(captured);
    },
  };
}

'use client';

import { randomUUID } from '@hachej/boring-files/platform';
import React, { useId, useRef, useState, useSyncExternalStore } from 'react';
import type { ReadResult } from '@hachej/boring-files';
import type { SaveResult } from '@hachej/boring-ui-kit/resources';
import type { TaskListController } from './task-list-controller';
import type { TaskListOperation } from './task-list-document';

export interface TaskListViewerProps {
  readonly controller: TaskListController;
  readonly title?: string;
  readonly className?: string;
}

export function TaskListViewer({ controller, title = 'Tasks', className }: TaskListViewerProps) {
  const state = useSyncExternalStore(controller.subscribe, controller.getSnapshot, controller.getSnapshot);
  const current = useRef({ controller });
  if (current.current.controller !== controller) current.current = { controller };
  const owner = current.current;
  const [form, setForm] = useState({ owner, draftTitle: '', notice: '' });
  const draftTitle = form.owner === owner ? form.draftTitle : '';
  const notice = form.owner === owner ? form.notice : '';
  const updateForm = (patch: Partial<{ draftTitle: string; notice: string }>) => {
    if (current.current !== owner) return;
    setForm(previous => ({ ...(previous.owner === owner ? previous : { owner, draftTitle: '', notice: '' }), ...patch }));
  };
  const setDraftTitle = (value: string) => updateForm({ draftTitle: value });
  const setNotice = (value: string) => updateForm({ notice: value });
  const inputId = useId();
  const disabled = state.readOnly || state.lifecycle === 'disposed';
  const edit = (operations: readonly TaskListOperation[]) => {
    const result = controller.actions.edit(controller.actions.selection(), operations);
    setNotice(result.kind === 'applied' ? '' : `${result.kind}: ${result.reason}`);
    return result;
  };
  const run = async (action: () => Promise<ReadResult | SaveResult>) => {
    try {
      const result = await action();
      setNotice(result.kind === 'available' || result.kind === 'saved' ? ''
        : result.kind === 'missing' ? 'missing: Resource is missing'
        : `${result.kind}${'reason' in result ? `: ${result.reason}` : ''}`);
    }
    catch (error) { setNotice(String(error)); }
  };
  const save = state.save.kind === 'settled' ? state.save.result : undefined;
  return <section className={['boring-task-list-recipe', className].filter(Boolean).join(' ')} data-boring="task-list-viewer">
    <h2>{title}</h2>
    <p role="status" aria-live="polite">{state.lifecycle === 'disposed' ? 'Closed' : state.readOnly ? 'Read only' : state.dirty ? 'Unsaved changes' : 'Saved'}
      {state.save.kind === 'pending' ? ' · Saving' : save ? ` · ${save.kind}${'reason' in save ? `: ${save.reason}` : ''}` : ''}
      {state.remote ? ' · Remote changes available' : ''}</p>
    <ul>{state.document.items.map(item => <li key={item.id} data-task-id={item.id}>
      <label><input type="checkbox" aria-label={`Complete ${item.title}`} checked={item.completed} disabled={disabled}
        onChange={event => edit([{ kind: 'set-completed', id: item.id, completed: event.target.checked }])} />{item.title}</label>
      <button type="button" aria-label={`Remove ${item.title}`} disabled={disabled} onClick={() => edit([{ kind: 'remove', id: item.id }])}>Remove</button>
    </li>)}</ul>
    <form onSubmit={event => { event.preventDefault(); if (edit([{ kind: 'add', id: randomUUID(), title: draftTitle }]).kind === 'applied') setDraftTitle(''); }}>
      <label htmlFor={inputId}>New task</label><input id={inputId} value={draftTitle} disabled={disabled} onChange={event => setDraftTitle(event.target.value)} />
      <button type="submit" disabled={disabled || !draftTitle.trim()}>Add task</button>
    </form>
    <div className="boring-task-list-actions">
      <button type="button" disabled={disabled || !state.dirty || state.save.kind === 'pending'} onClick={() => void run(() => controller.flush(controller.actions.selection()))}>Save</button>
      <button type="button" disabled={state.lifecycle === 'disposed'} onClick={() => void run(controller.actions.refresh)}>Refresh</button>
      <button type="button" disabled={disabled || (!state.dirty && !state.remote)} onClick={() => void run(controller.actions.discardToRemote)}>Discard</button>
      <button type="button" disabled={state.lifecycle === 'disposed' || save?.kind !== 'unknown'} onClick={() => void run(controller.actions.reconcile)}>Reconcile</button>
      <button type="button" disabled={state.lifecycle === 'disposed' || save?.kind !== 'unknown'} onClick={() => void run(controller.actions.abandon)}>Abandon save</button>
    </div>
    {notice && <p role="alert">{notice}</p>}
  </section>;
}
